#include "3mm.h"

extern "C" {

void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for tiling/staging
    double local_A[NI][NK];
    double local_B[NK][NJ];
    double local_C[NJ][NM];
    double local_D[NM][NL];
    double local_E[NI][NJ];
    double local_F[NJ][NL];
    double local_G[NI][NL];

#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_B cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_C cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_D cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_E cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_F cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_G cyclic factor=8 dim=2

    // Load A
    load_A_i: for (int i = 0; i < NI; i++) {
        load_A_k: for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }
    }

    // Load B
    load_B_k: for (int k = 0; k < NK; k++) {
        load_B_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }
    }

    // Load C
    load_C_i: for (int i = 0; i < NJ; i++) {
        load_C_k: for (int k = 0; k < NM; k++) {
#pragma HLS PIPELINE II=1
            local_C[i][k] = C[i][k];
        }
    }

    // Load D
    load_D_k: for (int k = 0; k < NM; k++) {
        load_D_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            local_D[k][j] = D[k][j];
        }
    }

    // Compute E = A * B
    loop_E_i: for (int i = 0; i < NI; i++) {
        loop_E_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_E_k: for (int k = 0; k < NK; ++k) {
#pragma HLS UNROLL factor=8
                sum += local_A[i][k] * local_B[k][j];
            }
            local_E[i][j] = sum;
        }
    }

    // Compute F = C * D
    loop_F_i: for (int i = 0; i < NJ; i++) {
        loop_F_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_F_k: for (int k = 0; k < NM; ++k) {
#pragma HLS UNROLL factor=8
                sum += local_C[i][k] * local_D[k][j];
            }
            local_F[i][j] = sum;
        }
    }

    // Compute G = E * F
    loop_G_i: for (int i = 0; i < NI; i++) {
        loop_G_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_G_k: for (int k = 0; k < NJ; ++k) {
#pragma HLS UNROLL factor=8
                sum += local_E[i][k] * local_F[k][j];
            }
            local_G[i][j] = sum;
        }
    }

    // Write back E
    write_E_i: for (int i = 0; i < NI; i++) {
        write_E_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            E[i][j] = local_E[i][j];
        }
    }

    // Write back F
    write_F_i: for (int i = 0; i < NJ; i++) {
        write_F_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            F[i][j] = local_F[i][j];
        }
    }

    // Write back G
    write_G_i: for (int i = 0; i < NI; i++) {
        write_G_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            G[i][j] = local_G[i][j];
        }
    }
}

} // extern "C"
