    }

    write_G_i: for (int i = 0; i < NI; i++) {
        write_G_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=NL max=NL
#pragma HLS DEPENDENCE variable=local_G inter false
            G[i][j] = local_G[i][j];
        }
    }
}

